const data = $input.all();
let output = '';

const usefulKeys = [
  'object_data.name',
  'object_data.sport_type',
  'object_data.distance',
  'object_data.moving_time',
  'object_data.total_elevation_gain',
  'object_data.calories',
  'object_data.average_speed',
  'object_data.workout_type'
];


function flattenJson(obj, prefix = '') {
  let str = '';
  for (const key in obj) {
    const fullKey = prefix ? `${prefix}.${key}` : key;
    if (typeof obj[key] === 'object' && obj[key] !== null) {
      str += flattenJson(obj[key], fullKey);
    } else {
      if (usefulKeys.includes(fullKey)) {
        str += `${fullKey}: ${obj[key]}\n`;
      }
    }
  }
  return str;
}

data.forEach(item => {
  output += flattenJson(item.json);
  output += '\n---\n';
});

return [{ json: { data: output } }];
